[metadata] {"type": "create", "filePath": "/app/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <title>Every Child Deserves to Learn - Infographic Poster</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=Oswald:wght@500;600;700&display=swap');

        * { margin: 0; padding: 0; box-sizing: border-box; }

        html, body {
            width: 2400px;
            height: 3400px;
            overflow: hidden;
        }

        body {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
            background: #0B1930;
        }

        .poster {
            width: 2400px;
            height: 3400px;
            display: flex;
            flex-direction: column;
        }

        /* ===== HERO SECTION ===== */
        .hero {
            background: linear-gradient(160deg, #0B1930 0%, #0F2340 40%, #132B50 70%, #0E2040 100%);
            padding: 60px 120px 50px;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            position: relative;
            flex: 0 0 780px;
            overflow: hidden;
        }

        .hero::before {
            content: '';
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            background:
                radial-gradient(ellipse 600px 400px at 15% 80%, rgba(28,171,226,0.08) 0%, transparent 100%),
                radial-gradient(ellipse 500px 300px at 85% 20%, rgba(242,106,33,0.06) 0%, transparent 100%),
                radial-gradient(ellipse 800px 600px at 50% 50%, rgba(28,171,226,0.04) 0%, transparent 100%);
            pointer-events: none;
        }

        .hero-deco {
            position: absolute;
            border: 2px solid rgba(28,171,226,0.12);
            border-radius: 50%;
        }
        .hero-deco-1 { width: 320px; height: 320px; top: -100px; right: -80px; }
        .hero-deco-2 { width: 200px; height: 200px; bottom: -50px; left: -40px; }
        .hero-deco-3 { width: 140px; height: 140px; top: 80px; left: 100px; border-color: rgba(255,194,14,0.1); }
        .hero-deco-4 { width: 80px; height: 80px; bottom: 120px; right: 200px; border-color: rgba(242,106,33,0.1); }

        .hero-brand {
            font-size: 20px;
            font-weight: 700;
            letter-spacing: 12px;
            color: #1CABE2;
            margin-bottom: 45px;
            position: relative;
            text-transform: uppercase;
        }

        .hero-headline {
            font-family: 'Oswald', 'Inter', sans-serif;
            font-size: 260px;
            font-weight: 700;
            color: #FFFFFF;
            line-height: 0.92;
            letter-spacing: -4px;
            position: relative;
        }

        .hero-headline .accent {
            color: #1CABE2;
        }

        .hero-divider {
            width: 160px;
            height: 5px;
            background: linear-gradient(90deg, #1CABE2, #FFC20E);
            margin: 32px auto;
            position: relative;
            border-radius: 3px;
        }

        .hero-subtitle {
            font-size: 36px;
            font-weight: 500;
            color: rgba(255,255,255,0.88);
            position: relative;
            max-width: 1400px;
            line-height: 1.35;
        }

        .hero-tagline {
            font-size: 26px;
            font-weight: 600;
            color: #1CABE2;
            margin-top: 24px;
            position: relative;
            letter-spacing: 6px;
            text-transform: uppercase;
        }

        /* ===== STATS SECTION ===== */
        .stats {
            background: linear-gradient(135deg, #1CABE2 0%, #1590C0 40%, #374EA2 100%);
            padding: 45px 100px;
            display: flex;
            justify-content: space-between;
            align-items: stretch;
            gap: 28px;
            flex: 0 0 370px;
        }

        .stat-card {
            flex: 1;
            background: rgba(255,255,255,0.12);
            backdrop-filter: blur(10px);
            border-radius: 20px;
            padding: 32px 24px;
            text-align: center;
            border: 1px solid rgba(255,255,255,0.18);
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
        }

        .stat-value {
            font-family: 'Oswald', 'Inter', sans-serif;
            font-size: 72px;
            font-weight: 700;
            color: #FFFFFF;
            line-height: 1;
            margin-bottom: 12px;
        }

        .stat-label {
            font-size: 16px;
            font-weight: 500;
            color: rgba(255,255,255,0.85);
            line-height: 1.4;
        }

        /* ===== BARRIERS SECTION ===== */
        .barriers {
            background: #FFFFFF;
            padding: 50px 90px 40px;
            flex: 0 0 820px;
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        .section-header {
            text-align: center;
            margin-bottom: 30px;
            flex-shrink: 0;
        }

        .section-title {
            font-family: 'Oswald', 'Inter', sans-serif;
            font-size: 44px;
            font-weight: 700;
            color: #0B1930;
            letter-spacing: 2px;
            text-transform: uppercase;
        }

        .section-line {
            width: 80px;
            height: 4px;
            margin: 12px auto 0;
            border-radius: 2px;
        }

        .barriers .section-line { background: #F26A21; }

        .barriers-grid {
            display: grid;
            grid-template-columns: repeat(5, 1fr);
            gap: 22px;
            flex: 1;
            width: 100%;
        }

        .barrier-card {
            background: #F8FAFB;
            border-radius: 16px;
            padding: 32px 20px 28px;
            text-align: center;
            border-top: 4px solid;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: flex-start;
        }

        .barrier-card:nth-child(1) { border-color: #F26A21; }
        .barrier-card:nth-child(2) { border-color: #1CABE2; }
        .barrier-card:nth-child(3) { border-color: #374EA2; }
        .barrier-card:nth-child(4) { border-color: #FFC20E; }
        .barrier-card:nth-child(5) { border-color: #0B1930; }

        .barrier-icon {
            width: 68px;
            height: 68px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 18px;
        }

        .barrier-card:nth-child(1) .barrier-icon { background: rgba(242,106,33,0.12); }
        .barrier-card:nth-child(2) .barrier-icon { background: rgba(28,171,226,0.12); }
        .barrier-card:nth-child(3) .barrier-icon { background: rgba(55,78,162,0.12); }
        .barrier-card:nth-child(4) .barrier-icon { background: rgba(255,194,14,0.15); }
        .barrier-card:nth-child(5) .barrier-icon { background: rgba(11,25,48,0.08); }

        .barrier-icon svg {
            width: 32px;
            height: 32px;
            fill: none;
            stroke: currentColor;
            stroke-width: 2;
            stroke-linecap: round;
            stroke-linejoin: round;
        }

        .barrier-card:nth-child(1) .barrier-icon svg { color: #F26A21; }
        .barrier-card:nth-child(2) .barrier-icon svg { color: #1CABE2; }
        .barrier-card:nth-child(3) .barrier-icon svg { color: #374EA2; }
        .barrier-card:nth-child(4) .barrier-icon svg { color: #D4A010; }
        .barrier-card:nth-child(5) .barrier-icon svg { color: #0B1930; }

        .barrier-title {
            font-size: 20px;
            font-weight: 700;
            color: #0B1930;
            margin-bottom: 10px;
            line-height: 1.2;
        }

        .barrier-desc {
            font-size: 15px;
            color: #5A6578;
            line-height: 1.5;
        }

        .barrier-stat {
            font-family: 'Oswald', 'Inter', sans-serif;
            font-size: 26px;
            font-weight: 600;
            margin-top: 12px;
        }

        .barrier-card:nth-child(1) .barrier-stat { color: #F26A21; }
        .barrier-card:nth-child(3) .barrier-stat { color: #374EA2; }
        .barrier-card:nth-child(4) .barrier-stat { color: #D4A010; }

        /* ===== FOCUS AREAS SECTION ===== */
        .focus-areas {
            background: #F0F9FC;
            padding: 50px 90px 40px;
            flex: 0 0 720px;
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        .focus-areas .section-line { background: #1CABE2; }

        .focus-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 22px;
            flex: 1;
            width: 100%;
        }

        .focus-card {
            background: #FFFFFF;
            border-radius: 16px;
            padding: 28px 24px;
            display: flex;
            align-items: flex-start;
            gap: 18px;
            border-left: 4px solid #1CABE2;
            box-shadow: 0 2px 12px rgba(28,171,226,0.08);
        }

        .focus-card:nth-child(2) { border-left-color: #374EA2; }
        .focus-card:nth-child(3) { border-left-color: #F26A21; }
        .focus-card:nth-child(4) { border-left-color: #FFC20E; }
        .focus-card:nth-child(5) { border-left-color: #0B1930; }
        .focus-card:nth-child(6) { border-left-color: #0E8BB5; }

        .focus-icon {
            width: 52px;
            height: 52px;
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
        }

        .focus-card:nth-child(1) .focus-icon { background: rgba(28,171,226,0.1); }
        .focus-card:nth-child(2) .focus-icon { background: rgba(55,78,162,0.1); }
        .focus-card:nth-child(3) .focus-icon { background: rgba(242,106,33,0.1); }
        .focus-card:nth-child(4) .focus-icon { background: rgba(255,194,14,0.12); }
        .focus-card:nth-child(5) .focus-icon { background: rgba(11,25,48,0.06); }
        .focus-card:nth-child(6) .focus-icon { background: rgba(14,139,181,0.1); }

        .focus-icon svg {
            width: 26px;
            height: 26px;
            fill: none;
            stroke: currentColor;
            stroke-width: 2;
            stroke-linecap: round;
            stroke-linejoin: round;
        }

        .focus-card:nth-child(1) .focus-icon svg { color: #1CABE2; }
        .focus-card:nth-child(2) .focus-icon svg { color: #374EA2; }
        .focus-card:nth-child(3) .focus-icon svg { color: #F26A21; }
        .focus-card:nth-child(4) .focus-icon svg { color: #D4A010; }
        .focus-card:nth-child(5) .focus-icon svg { color: #0B1930; }
        .focus-card:nth-child(6) .focus-icon svg { color: #0E8BB5; }

        .focus-content { flex: 1; }

        .focus-title {
            font-size: 18px;
            font-weight: 700;
            color: #0B1930;
            margin-bottom: 6px;
        }

        .focus-desc {
            font-size: 14px;
            color: #5A6578;
            line-height: 1.5;
        }

        /* ===== CTA SECTION ===== */
        .cta {
            background: linear-gradient(135deg, #F26A21 0%, #E85D15 40%, #FFC20E 100%);
            padding: 50px 160px 55px;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            flex: 1;
            position: relative;
            overflow: hidden;
        }

        .cta::before {
            content: '';
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            background:
                radial-gradient(ellipse 500px 300px at 20% 80%, rgba(255,255,255,0.08) 0%, transparent 100%),
                radial-gradient(ellipse 400px 200px at 80% 20%, rgba(255,255,255,0.06) 0%, transparent 100%);
            pointer-events: none;
        }

        .cta-title {
            font-family: 'Oswald', 'Inter', sans-serif;
            font-size: 42px;
            font-weight: 700;
            color: #FFFFFF;
            margin-bottom: 18px;
            position: relative;
            letter-spacing: 2px;
            text-transform: uppercase;
        }

        .cta-text {
            font-size: 21px;
            color: rgba(255,255,255,0.95);
            max-width: 1500px;
            line-height: 1.65;
            position: relative;
            margin-bottom: 16px;
        }

        .cta-sdg {
            display: inline-block;
            font-size: 16px;
            font-weight: 700;
            color: #F26A21;
            background: #FFFFFF;
            padding: 10px 28px;
            border-radius: 30px;
            letter-spacing: 2px;
            margin: 12px 0;
            position: relative;
        }

        .cta-closing {
            font-size: 22px;
            font-weight: 600;
            color: #FFFFFF;
            margin-top: 10px;
            position: relative;
        }

        .cta-source {
            font-size: 13px;
            color: rgba(255,255,255,0.55);
            margin-top: 18px;
            position: relative;
        }
    </style>
</head>
<body>
    <div class="poster">
        <!-- ===== HERO SECTION ===== -->
        <section class="hero">
            <div class="hero-deco hero-deco-1"></div>
            <div class="hero-deco hero-deco-2"></div>
            <div class="hero-deco hero-deco-3"></div>
            <div class="hero-deco hero-deco-4"></div>
            <div class="hero-brand">UNICEF</div>
            <div class="hero-headline">250 <span class="accent">MILLION</span></div>
            <div class="hero-divider"></div>
            <div class="hero-subtitle">Children &amp; Adolescents Out of School Worldwide</div>
            <div class="hero-tagline">Every Child Deserves to Learn</div>
        </section>

        <!-- ===== STATS SECTION ===== -->
        <section class="stats">
            <div class="stat-card">
                <div class="stat-value">70%</div>
                <div class="stat-label">Cannot read a simple text by age 10 in low- &amp; middle-income countries</div>
            </div>
            <div class="stat-card">
                <div class="stat-value">190+</div>
                <div class="stat-label">Countries with UNICEF education programmes</div>
            </div>
            <div class="stat-card">
                <div class="stat-value">2.5&times;</div>
                <div class="stat-label">Girls more likely to be excluded from education in crisis settings</div>
            </div>
            <div class="stat-card">
                <div class="stat-value">~49%</div>
                <div class="stat-label">Children with disabilities out of school in low-income countries</div>
            </div>
        </section>

        <!-- ===== BARRIERS SECTION ===== -->
        <section class="barriers">
            <div class="section-header">
                <h2 class="section-title">Barriers to Education</h2>
                <div class="section-line"></div>
            </div>
            <div class="barriers-grid">
                <!-- Armed Conflict -->
                <div class="barrier-card">
                    <div class="barrier-icon">
                        <svg viewBox="0 0 24 24"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
                    </div>
                    <div class="barrier-title">Armed Conflict</div>
                    <div class="barrier-desc">Schools destroyed, teachers displaced, children traumatized</div>
                    <div class="barrier-stat">2.5&times; girls excluded</div>
                </div>
                <!-- Poverty -->
                <div class="barrier-card">
                    <div class="barrier-icon">
                        <svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/><path d="M9 8h4a2 2 0 0 1 0 4H9z"/></svg>
                    </div>
                    <div class="barrier-title">Poverty</div>
                    <div class="barrier-desc">Families cannot afford fees, uniforms, or supplies, and may rely on child labour</div>
                </div>
                <!-- Gender Inequality -->
                <div class="barrier-card">
                    <div class="barrier-icon">
                        <svg viewBox="0 0 24 24"><circle cx="12" cy="7" r="4"/><path d="M5.5 21a6.5 6.5 0 0 1 13 0"/><line x1="18" y1="5" x2="22" y2="5"/><line x1="20" y1="3" x2="20" y2="7"/></svg>
                    </div>
                    <div class="barrier-title">Gender Inequality</div>
                    <div class="barrier-desc">Social norms limit girls' access to education, especially at secondary level</div>
                </div>
                <!-- Disability -->
                <div class="barrier-card">
                    <div class="barrier-icon">
                        <svg viewBox="0 0 24 24"><circle cx="12" cy="5" r="2"/><path d="M10 22v-6H7l3-7h4l3 7h-3v6"/><circle cx="12" cy="19" r="3"/><line x1="12" y1="16" x2="12" y2="19"/></svg>
                    </div>
                    <div class="barrier-title">Disability</div>
                    <div class="barrier-desc">Nearly half of children with disabilities never enter a classroom</div>
                    <div class="barrier-stat">~49%</div>
                </div>
                <!-- Climate Change -->
                <div class="barrier-card">
                    <div class="barrier-icon">
                        <svg viewBox="0 0 24 24"><path d="M18 10h-1.26A8 8 0 1 0 9 20h9a5 5 0 0 0 0-10z"/></svg>
                    </div>
                    <div class="barrier-title">Climate Change</div>
                    <div class="barrier-desc">Floods, droughts, and extreme weather increasingly disrupt schooling</div>
                </div>
            </div>
        </section>

        <!-- ===== FOCUS AREAS SECTION ===== -->
        <section class="focus-areas">
            <div class="section-header">
                <h2 class="section-title">UNICEF's Education Focus Areas</h2>
                <div class="section-line"></div>
            </div>
            <div class="focus-grid">
                <!-- Early Childhood Development -->
                <div class="focus-card">
                    <div class="focus-icon">
                        <svg viewBox="0 0 24 24"><circle cx="12" cy="8" r="5"/><path d="M3 21v-2a7 7 0 0 1 7-7h4a7 7 0 0 1 7 7v2"/></svg>
                    </div>
                    <div class="focus-content">
                        <div class="focus-title">Early Childhood Development</div>
                        <div class="focus-desc">Building strong foundations through pre-primary education and school readiness programmes</div>
                    </div>
                </div>
                <!-- Inclusive Education -->
                <div class="focus-card">
                    <div class="focus-icon">
                        <svg viewBox="0 0 24 24"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
                    </div>
                    <div class="focus-content">
                        <div class="focus-title">Inclusive Education</div>
                        <div class="focus-desc">Ensuring children with disabilities and marginalized groups can access and thrive in school</div>
                    </div>
                </div>
                <!-- Gender Equality -->
