(async () => {
    const browser = await chromium.launch({ headless: true });
    const page = await browser.newPage({ viewport: { width: 2400, height: 3400 } });

    // Capture console messages
    page.on('console', msg => console.log('CONSOLE:', msg.type(), msg.text()));
    page.on('pageerror', err => console.log('ERROR:', err.message));

    await page.goto('file:///app/poster.html', { waitUntil: 'networkidle' });
    await page.evaluate(() => document.fonts.ready);

    // Wait for infographics
    await page.waitForFunction(() => window._allInfographicsReady === true, { timeout: 15000 }).catch(() => {
        console.log('Infographic timeout - checking state...');
    });
    await page.waitForTimeout(3000);

    // Check infographic container states
    const state = await page.evaluate(() => {
        const bc = document.querySelector('#barriers-container');
        const fc = document.querySelector('#focus-container');
        return {
            barriersHTML: bc ? bc.innerHTML.substring(0, 200) : 'NOT FOUND',
            barriersChildCount: bc ? bc.childElementCount : -1,
            focusHTML: fc ? fc.innerHTML.substring(0, 200) : 'NOT FOUND',
            focusChildCount: fc ? fc.childElementCount : -1,
            igReady: window._allInfographicsReady,
            igRendered: window._igRendered,
        };
    });
    console.log('State:', JSON.stringify(state, null, 2));

    await browser.close();
})();
