const { chromium } = require('playwright');

(async () => {
    const browser = await chromium.launch({ headless: true });
    const page = await browser.newPage({ viewport: { width: 2400, height: 3400 } });

    await page.goto('file:///app/poster.html', { waitUntil: 'networkidle' });
    await page.evaluate(() => document.fonts.ready);
    await page.waitForFunction(() => window._allInfographicsReady === true, { timeout: 15000 });
    await page.waitForTimeout(3000);

    // Check infographic SVG details
    const svgInfo = await page.evaluate(() => {
        const bc = document.querySelector('#barriers-container svg');
        const fc = document.querySelector('#focus-container svg');

        const getSvgDetails = (svg) => {
            if (!svg) return null;
            const rect = svg.getBoundingClientRect();
            const bg = svg.querySelector('rect');
            return {
                width: rect.width,
                height: rect.height,
                viewBox: svg.getAttribute('viewBox'),
                bgRect: bg ? {
                    fill: bg.getAttribute('fill'),
                    width: bg.getAttribute('width'),
                    height: bg.getAttribute('height'),
                } : 'no bg rect',
                textElements: svg.querySelectorAll('text').length,
                groupCount: svg.querySelectorAll('g').length,
            };
        };

        return {
            barriers: getSvgDetails(bc),
            focus: getSvgDetails(fc),
            fontsLoaded: document.fonts.check('700px Oswald'),
            interLoaded: document.fonts.check('400px Inter'),
        };
    });

    console.log('SVG Details:', JSON.stringify(svgInfo, null, 2));

    await browser.close();
})();

