const { chromium } = require('playwright');

(async () => {
    const browser = await chromium.launch({ headless: true });
    const page = await browser.newPage({ viewport: { width: 2400, height: 3400 } });

    await page.goto('file:///app/poster.html', { waitUntil: 'networkidle' });
    await page.evaluate(() => document.fonts.ready);
    await page.waitForFunction(() => window._allInfographicsReady === true, { timeout: 15000 });
    await page.waitForTimeout(3000);

    // Check for foreignObject and other text rendering methods
    const textCheck = await page.evaluate(() => {
        const bc = document.querySelector('#barriers-container svg');
        const fc = document.querySelector('#focus-container svg');

        const checkSvg = (svg, name) => {
            if (!svg) return { name, error: 'no svg' };
            const foreignObjects = svg.querySelectorAll('foreignObject');
            const paths = svg.querySelectorAll('path');
            const rects = svg.querySelectorAll('rect');
            const circles = svg.querySelectorAll('circle');

            // Get first few foreignObject contents
            let foContents = [];
            foreignObjects.forEach((fo, i) => {
                if (i < 3) {
                    foContents.push({
                        width: fo.getAttribute('width'),
                        height: fo.getAttribute('height'),
                        innerHTML: fo.innerHTML.substring(0, 300),
                    });
                }
            });

            return {
                name,
                foreignObjectCount: foreignObjects.length,
                pathCount: paths.length,
                rectCount: rects.length,
                circleCount: circles.length,
                foContents,
            };
        };

        return {
            barriers: checkSvg(bc, 'barriers'),
            focus: checkSvg(fc, 'focus'),
        };
    });

    console.log('Text check:', JSON.stringify(textCheck, null, 2));

    await browser.close();
})();

