      icon graduation
theme
  palette #1CABE2 #374EA2 #F26A21 #FFC20E #0B1930 #0E8BB5`);
                    onIgRendered();
                } catch (e) {
                    console.warn('Focus infographic failed:', e);
                    onIgRendered();
                }
            }, 500);
        });
    </script>
