const { chromium } = require('playwright');
const path = require('path');

(async () => {
    const browser = await chromium.launch({ headless: true });
    const page = await browser.newPage({
        viewport: { width: 2400, height: 3400 },
        deviceScaleFactor: 1,
    });

    const htmlPath = path.resolve('/app/poster.html');
    await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle' });

    // Wait for fonts to fully load (including Google Fonts CDN)
    await page.evaluate(async () => {
        await document.fonts.ready;
        // Extra wait for Google Fonts that load via link tags
        await new Promise(r => setTimeout(r, 2000));
        await document.fonts.ready;
    });

    // Wait for AntV Infographic instances to render
    await page.waitForFunction(() => window._allInfographicsReady === true, { timeout: 20000 }).catch(() => {
        console.log('Infographic render check timed out, proceeding...');
    });

    // Settle time for SVG rendering
    await page.waitForTimeout(3000);

    // Check font loading status
    const fontStatus = await page.evaluate(() => ({
        oswald: document.fonts.check('700px Oswald'),
        inter: document.fonts.check('400px Inter'),
        allFonts: Array.from(document.fonts).map(f => `${f.family} ${f.weight} ${f.status}`).join('; '),
    }));
    console.log('Font status:', JSON.stringify(fontStatus));

    // Check section heights
    const sections = await page.evaluate(() => {
        return Array.from(document.querySelectorAll('.poster > section')).map((s, i) => ({
            i, cls: s.className, top: s.offsetTop, h: s.offsetHeight
        }));
    });
    console.log('Sections:', JSON.stringify(sections));

    await page.screenshot({
        path: '/app/output/final_poster.png',
        fullPage: false,
    });

    await browser.close();
    console.log('Poster saved to /app/output/final_poster.png');
})();

