const { chromium } = require('playwright');

(async () => {
    const browser = await chromium.launch({ headless: true });
    const page = await browser.newPage({ viewport: { width: 2400, height: 3400 } });

    await page.goto('file:///app/poster.html', { waitUntil: 'networkidle' });
    await page.evaluate(async () => {
        await document.fonts.ready;
        await new Promise(r => setTimeout(r, 3000));
        await document.fonts.ready;
    });
    await page.waitForFunction(() => window._allInfographicsReady === true, { timeout: 20000 }).catch(() => {});
    await page.waitForTimeout(3000);

    // Verify infographic content has visible text
    const igCheck = await page.evaluate(() => {
        const bc = document.querySelector('#barriers-container');
        const fc = document.querySelector('#focus-container');
        const getVisibleText = (el) => {
            if (!el) return 'MISSING';
            const texts = [];
            el.querySelectorAll('foreignObject span').forEach(s => texts.push(s.textContent));
            return texts.join(' | ');
        };
        return {
            barriersText: getVisibleText(bc),
            focusText: getVisibleText(fc),
        };
    });

    console.log('Barriers text:', igCheck.barriersText.substring(0, 300));
    console.log('Focus text:', igCheck.focusText.substring(0, 300));

    // Final high-quality screenshot
    await page.screenshot({
        path: '/app/output/final_poster.png',
        fullPage: false,
    });

    const fs = require('fs');
    const stats = fs.statSync('/app/output/final_poster.png');
    console.log(`Final poster: ${(stats.size / 1024 / 1024).toFixed(2)} MB`);

    await browser.close();
})();

