    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        html, body { width: 100%; height: 100%; background: #f5f5f5; }
        #container { width: 100%; height: 100%; }
        #export-btn {
            position: fixed; top: 16px; right: 16px; z-index: 999;
            padding: 8px 20px; background: #1CABE2; color: #fff;
            border: none; border-radius: 6px; cursor: pointer; font-size: 14px;
        }
    </style>
</head>
<body>
    <div id="container"></div>
    <button id="export-btn">Export SVG</button>
    <script src="/app/vendor/infographic.min.js"></script>
    <script>
        const infographic = new AntVInfographic.Infographic({
            container: '#container',
            width: '100%',
            height: '100%',
        });
        const syntax = `infographic list-grid-badge-card
data
  title Barriers to Education
  lists
    - label Armed Conflict
      desc Schools destroyed, teachers displaced, children traumatized
      icon shield
    - label Poverty
      desc Families cannot afford fees, uniforms, or supplies
      icon coin
    - label Gender Inequality
      desc Social norms limit girls access to education
      icon user
    - label Disability
      desc Nearly half of children with disabilities never enter a classroom
      icon accessibility
    - label Climate Change
      desc Floods, droughts, and extreme weather disrupt schooling
      icon cloud
theme
  palette #F26A21 #1CABE2 #374EA2 #FFC20E #0B1930`;

